  1 package nexusbench
  2 
  3 import (
  4     "context"
  5     "encoding/json"
  6     "errors"
  7     "fmt"
  8     "io/fs"
  9     "log/slog"
 10     "os"
 11     "os/exec"
 12     "path/filepath"
 13     "strings"
 14     "time"
 15 )
 16 
 17 const (
 18     secretsFileMode = 0o600
 19     secretsDirMode  = 0o700
 20     // gitCheckTimeout bounds the one git process the store may start.
 21     gitCheckTimeout = 10 * time.Second
 22     // redactedSecrets is what a Secrets shows in place of its values.
 23     redactedSecrets = "Secrets{redacted}"
 24 )
 25 
 26 // Secrets are the passwords of the bench. They live in the secrets file and
 27 // nowhere else: not in the descriptor, not in a manifest, not in an error.
 28 type Secrets struct {
 29     // AdminPassword is the current password of the admin account.
 30     AdminPassword string `json:"adminPassword"`
 31     // PendingAdminPassword is the new admin password, written before it is sent
 32     // to Nexus so that an interrupted change does not lose it.
 33     PendingAdminPassword string `json:"pendingAdminPassword,omitempty"`
 34     // PullPassword is the password of the read-only bench-pull account.
 35     PullPassword string `json:"pullPassword,omitempty"`
 36 }
 37 
 38 // String implements fmt.Stringer so that %v, %+v and %s never print a password.
 39 func (Secrets) String() string { return redactedSecrets }
 40 
 41 // GoString implements fmt.GoStringer so that %#v never prints a password.
 42 func (Secrets) GoString() string { return redactedSecrets }
 43 
 44 // LogValue implements slog.LogValuer so that a logger never records a password.
 45 func (Secrets) LogValue() slog.Value { return slog.StringValue(redactedSecrets) }
 46 
 47 // SecretStore keeps the Secrets of one bench (one context and namespace).
 48 type SecretStore interface {
 49     // Load returns the stored secrets; found is false, without an error, when
 50     // nothing is stored yet.
 51     Load() (s Secrets, found bool, err error)
 52     // Save replaces the stored secrets atomically.
 53     Save(Secrets) error
 54     // Remove deletes the stored secrets. It succeeds when there are none.
 55     Remove() error
 56 }
 57 
 58 // DefaultSecretsPath returns where the secrets of a bench live:
 59 // <state>/devdesk/nexus-bench/<context>/<namespace>/secrets.json, with <state>
 60 // the XDG_STATE_HOME variable, else ~/.local/state. The folder is outside every
 61 // repository and shared by all the worktrees of the project. getenv is os.Getenv
 62 // in production; an empty variable counts as unset.
 63 func DefaultSecretsPath(kubeContext, namespace string, getenv func(string) string) (string, error) {
 64     for _, part := range []string{kubeContext, namespace} {
 65         if part == "" || part == "." || part == ".." || strings.ContainsAny(part, `/\`) {
 66             return "", fmt.Errorf("%q cannot name a folder of the secrets path", part)
 67         }
 68     }
 69     state := getenv("XDG_STATE_HOME")
 70     if state == "" {
 71         home := getenv("HOME")
 72         if home == "" {
 73             home = getenv("USERPROFILE")
 74         }
 75         if home == "" {
 76             return "", errors.New("cannot place the secrets file: neither XDG_STATE_HOME nor HOME is set; set NEXUS_BENCH_SECRETS to a path outside the repository")
 77         }
 78         state = filepath.Join(home, ".local", "state")
 79     }
 80     return filepath.Join(state, "devdesk", "nexus-bench", kubeContext, namespace, "secrets.json"), nil
 81 }
 82 
 83 // fileStore is the SecretStore backed by one JSON file.
 84 type fileStore struct{ path string }
 85 
 86 // NewFileStore returns the store of the file at path. It touches nothing on
 87 // disk. A path inside a git working tree is refused unless git ignores it, so
 88 // that a secret cannot be committed by accident; a path outside every
 89 // repository is accepted without asking git.
 90 func NewFileStore(path string) (SecretStore, error) {
 91     if path == "" {
 92         return nil, errors.New("the secrets path is empty")
 93     }
 94     abs, err := filepath.Abs(path)
 95     if err != nil {
 96         return nil, fmt.Errorf("resolve the secrets path: %w", err)
 97     }
 98     if root, inRepo := findGitRoot(filepath.Dir(abs)); inRepo {
 99         ignored, err := gitIgnores(root, abs)
100         if err != nil {
101             return nil, &BenchError{
102                 Cause: fmt.Sprintf("the secrets path %s is inside the git repository %s and git could not tell whether it is ignored", abs, root),
103                 Check: "run git check-ignore -v on that path, or set NEXUS_BENCH_SECRETS to a path outside the repository",
104                 Err:   err,
105             }
106         }
107         if !ignored {
108             return nil, &BenchError{
109                 Cause: fmt.Sprintf("the secrets path %s is inside the git repository %s and is not ignored by git, so the passwords could be committed", abs, root),
110                 Check: "set NEXUS_BENCH_SECRETS to a path outside the repository, or add the file to .gitignore",
111             }
112         }
113     }
114     return &fileStore{path: abs}, nil
115 }
116 
117 // findGitRoot walks up from dir (which may not exist yet) to the first folder
118 // that holds a .git entry, a directory or a file as in a worktree.
119 func findGitRoot(dir string) (root string, ok bool) {
120     for {
121         if _, err := os.Lstat(filepath.Join(dir, ".git")); err == nil {
122             return dir, true
123         }
124         parent := filepath.Dir(dir)
125         if parent == dir {
126             return "", false
127         }
128         dir = parent
129     }
130 }
131 
132 // gitIgnores reports whether git ignores path inside the working tree at root.
133 // It is a variable so a test can replace the one process the package starts for
134 // the guard; kubectl.go stays the only file that starts one otherwise.
135 var gitIgnores = func(root, path string) (bool, error) {
136     ctx, cancel := context.WithTimeout(context.Background(), gitCheckTimeout)
137     defer cancel()
138     cmd := exec.CommandContext(ctx, "git", "-C", root, "check-ignore", "-q", "--", path) //nolint:gosec // fixed arguments, the paths come from the caller's own configuration
139     cmd.Env = gitEnvironment()
140     err := cmd.Run()
141     if err == nil {
142         return true, nil // exit 0: the path is ignored
143     }
144     var exit *exec.ExitError
145     if errors.As(err, &exit) && exit.ExitCode() == 1 {
146         return false, nil // exit 1: the path is not ignored
147     }
148     return false, err // git missing, exit 128 (not a repository, bad path), timeout
149 }
150 
151 // gitEnvironment is the environment of the git process: the caller's, without
152 // the variables that point git at a repository. Inherited, GIT_DIR and its
153 // siblings would make git judge another repository than the one holding the
154 // path, and the guard would answer for the wrong one. Names are compared in
155 // upper case because Windows environment names are case-insensitive.
156 func gitEnvironment() []string {
157     var env []string
158     for _, kv := range os.Environ() {
159         name, _, _ := strings.Cut(kv, "=")
160         switch strings.ToUpper(name) {
161         case "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR", "GIT_OBJECT_DIRECTORY", "GIT_NAMESPACE":
162             continue
163         }
164         env = append(env, kv)
165     }
166     return env
167 }
168 
169 // Load implements SecretStore. The error never carries the content of the
170 // file: a corrupt file may hold a password.
171 func (s *fileStore) Load() (Secrets, bool, error) {
172     data, err := os.ReadFile(s.path)
173     if errors.Is(err, fs.ErrNotExist) {
174         return Secrets{}, false, nil
175     }
176     if err != nil {
177         return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
178     }
179     var out Secrets
180     if err := json.Unmarshal(data, &out); err != nil {
181         return Secrets{}, false, &BenchError{
182             Cause: fmt.Sprintf("the secrets file %s is not valid", s.path),
183             Check: "delete the file and run the bench again, or restore it from a copy; its content is not shown",
184             Err:   err,
185         }
186     }
187     return out, true, nil
188 }
189 
190 // Save implements SecretStore.
191 func (s *fileStore) Save(secrets Secrets) error {
192     data, err := json.MarshalIndent(secrets, "", "  ")
193     if err != nil {
194         return fmt.Errorf("encode the secrets: %w", err)
195     }
196     return writeFileAtomic(s.path, append(data, '\n'), secretsFileMode, secretsDirMode)
197 }
198 
199 // Remove implements SecretStore. It deletes the file, then its folder when
200 // that is empty; a folder that holds anything else stays.
201 func (s *fileStore) Remove() error {
202     if err := os.Remove(s.path); err != nil && !errors.Is(err, fs.ErrNotExist) {
203         return fmt.Errorf("remove the secrets file: %w", err)
204     }
205     dir := filepath.Dir(s.path)
206     entries, err := os.ReadDir(dir)
207     if errors.Is(err, fs.ErrNotExist) || (err == nil && len(entries) > 0) {
208         return nil
209     }
210     if err != nil {
211         return fmt.Errorf("read the secrets folder: %w", err)
212     }
213     if err := os.Remove(dir); err != nil && !errors.Is(err, fs.ErrNotExist) {
214         return fmt.Errorf("remove the secrets folder: %w", err)
215     }
216     return nil
217 }
218 
219 // writeFileAtomic writes data to path through a temporary file of the same
220 // folder and a rename, so a reader sees the old file or the new one, never a
221 // partial one. Missing folders are created with dirMode. The temporary file is
222 // removed when anything fails. The error text holds paths, never data.
223 func writeFileAtomic(path string, data []byte, fileMode, dirMode os.FileMode) (err error) {
224     dir := filepath.Dir(path)
225     if err := os.MkdirAll(dir, dirMode); err != nil {
226         return fmt.Errorf("create the folder %s: %w", dir, err)
227     }
228     tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*.tmp")
229     if err != nil {
230         return fmt.Errorf("create a temporary file in %s: %w", dir, err)
231     }
232     defer func() {
233         if err != nil {
234             _ = tmp.Close()
235             _ = os.Remove(tmp.Name())
236         }
237     }()
238     if _, err = tmp.Write(data); err != nil {
239         return fmt.Errorf("write %s: %w", tmp.Name(), err)
240     }
241     if err = tmp.Chmod(fileMode); err != nil {
242         return fmt.Errorf("set the mode of %s: %w", tmp.Name(), err)
243     }
244     if err = tmp.Sync(); err != nil {
245         return fmt.Errorf("sync %s: %w", tmp.Name(), err)
246     }
247     if err = tmp.Close(); err != nil {
248         return fmt.Errorf("close %s: %w", tmp.Name(), err)
249     }
250     if err = os.Rename(tmp.Name(), path); err != nil {
251         return fmt.Errorf("replace %s: %w", path, err)
252     }
253     syncDir(dir)
254     return nil
255 }
256 
257 // syncDir flushes the folder entry written by the rename. Syncing the file
258 // alone does not make the new name durable: after a power cut the folder could
259 // still list the old file, and a password written just before it was sent to
260 // Nexus would be lost. It is best effort: Windows cannot open a folder for
261 // syncing and some file systems do not support it, and the file is already
262 // replaced either way, so every error is ignored.
263 func syncDir(dir string) {
264     d, err := os.Open(dir)
265     if err != nil {
266         return
267     }
268     _ = d.Sync()
269     _ = d.Close()
270 }
