  3 import "strings"
  4 
  5 // ErrKind says which of the failures of the bench (D-F) a BenchError is. The
  6 // zero value is Unclassified on purpose: an error nobody classified must not
  7 // pass for the first named kind.
  8 type ErrKind int
  9 
 10 // The kinds of D-F, in the order the bench meets them.
 11 const (
 12     // Unclassified is a failure none of the other kinds describes.
 13     Unclassified ErrKind = iota
 14     KubectlMissing
 15     ContextNotFound
 16     ClusterUnreachable
 17     Forbidden
 18     NamespaceForeign
 19     NamespaceMissing
 20     NodePortTaken
 21     AdmissionDenied
 22     PodPending
 23     ImagePull
 24     Crash
 25     Deadline
 26     RESTUnreachable
 27     ProvisionFailed
 28 )
 29 
 30 // BenchError is the one error type of the bench: a probable cause and what to
 31 // check, both in English and both free of secrets. Err is the underlying error,
 32 // kept for errors.Is and errors.As; Error never prints it, because the text of
 33 // a failed sub-process can carry a credential.
 34 type BenchError struct {
 35     Kind  ErrKind
 36     Cause string
 37     Check string
 38     Err   error
 39 }
 40 
 41 // Error returns "<Cause>. Check: <Check>".
 42 func (e *BenchError) Error() string {
 43     return e.Cause + ". Check: " + e.Check
 44 }
 45 
 46 // Unwrap returns the underlying error, or nil when there is none.
 47 func (e *BenchError) Unwrap() error { return e.Err }
 48 
 49 // classifyKubectl maps the stderr of a failed kubectl call to a kind. The text
 50 // of kubectl changes between versions, so this is a fallback for the cases the
 51 // structured calls (exit status, JSON) cannot tell apart; a text it does not
 52 // know is Unclassified.
 53 func classifyKubectl(stderr string) ErrKind {
 54     s := strings.ToLower(stderr)
 55     switch {
 56     // The more specific reason wins: a webhook refusal is reported by the API
 57     // server as Forbidden too.
 58     case strings.Contains(s, "admission webhook") && strings.Contains(s, "denied"):
 59         return AdmissionDenied
 60     case strings.Contains(s, "provided port is already allocated"),
 61         strings.Contains(s, "provided port is not in the valid range"):
 62         return NodePortTaken
 63     case strings.Contains(s, "forbidden"):
 64         return Forbidden
 65     case strings.Contains(s, "unable to connect to the server"),
 66         strings.Contains(s, "connection refused"),
 67         strings.Contains(s, "i/o timeout"),
 68         strings.Contains(s, "tls handshake timeout"):
 69         return ClusterUnreachable
 70     }
 71     return Unclassified
 72 }
 73 
 74 // isNotFound reports whether stderr is the kubectl answer for an absent object.
 75 func isNotFound(stderr string) bool {
 76     return strings.Contains(stderr, "(NotFound)")
 77 }

  1 package nexusbench
  2 
  3 import (
  4     "context"
  5     "encoding/json"
  6     "fmt"
  7     "slices"
  8     "strings"
  9 )
 10 
 11 // Op is what a run of the bench is about to do; it decides which checks the
 12 // preflight makes.
 13 type Op int
 14 
 15 const (
 16     OpUp Op = iota
 17     OpProvision
 18     OpDown
 19     OpStatus
 20 )
 21 
 22 // PreflightResult is what a successful preflight learned about the cluster.
 23 type PreflightResult struct {
 24     // NamespaceExists is true when the bench namespace is there.
 25     NamespaceExists bool
 26     // NamespaceOurs is true when it carries our managed-by label.
 27     NamespaceOurs bool
 28     // NodeIP is the InternalIP of the first node that reports one; empty when
 29     // none does, which is not an error (the other hosts still work). It is not
 30     // read for OpDown.
 31     NodeIP string
 32 }
 33 
 34 const (
 35     // managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
 36     // puts on the namespace; down deletes a namespace only when it carries it.
 37     managedByLabel = "app.kubernetes.io/managed-by"
 38     managedByValue = "devdesk-nexus-bench"
 39 
 40     // nexusServiceName is the Service 30-service.yaml.tmpl creates.
 41     nexusServiceName = "nexus"
 42 
 43     // requestTimeout bounds every call that reaches the API server.
 44     requestTimeout = "--request-timeout=10s"
 45 )
 46 
 47 // permissionScope says where a can-i question applies.
 48 type permissionScope int
 49 
 50 const (
 51     scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
 52     scopeNamespace                        // -n <namespace>
 53     scopeAll                              // -A
 54 )
 55 
 56 // permission is one "kubectl auth can-i" question the preflight asks.
 57 type permission struct {
 58     verb, resource string
 59     scope          permissionScope
 60 }
 61 
 62 // permissionsByOp is the list F2 of the plan: what each operation needs. An
 63 // operation absent from the map (status) writes nothing and asks nothing.
 64 var permissionsByOp = map[Op][]permission{
 65     OpUp: {
 66         {"create", "namespaces", scopeCluster},
 67         {"create", "persistentvolumeclaims", scopeNamespace},
 68         {"create", "services", scopeNamespace},
 69         {"create", "deployments", scopeNamespace},
 70         {"create", "secrets", scopeNamespace},
 71         {"create", "pods/exec", scopeNamespace},
 72         {"list", "services", scopeAll},
 73         // Server-side apply is a PATCH, also on a second run, and Deploy reads
 74         // the pods and the claims of the namespace while it waits.
 75         {"patch", "deployments", scopeNamespace},
 76         {"patch", "services", scopeNamespace},
 77         {"patch", "persistentvolumeclaims", scopeNamespace},
 78         {"get", "pods", scopeNamespace},
 79         {"list", "pods", scopeNamespace},
 80         {"get", "persistentvolumeclaims", scopeNamespace},
 81         {"list", "persistentvolumeclaims", scopeNamespace},
 82     },
 83     OpProvision: {{"create", "pods/exec", scopeNamespace}},
 84     OpDown:      {{"delete", "namespaces", scopeCluster}},
 85 }
 86 
 87 // RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
 88 // returns what it learned. Nothing is written to the cluster, whatever the
 89 // outcome: a failure here means no write was ever issued. The checks run in a
 90 // fixed order and stop at the first failure, so nothing is asked of a cluster
 91 // the context does not reach:
 92 //
 93 //  1. the parameters (no call at all)
 94 //  2. the context is in the kubeconfig
 95 //  3. the API server answers /readyz
 96 //  4. the can-i questions of the operation
 97 //  5. the namespace: absent, ours, or foreign
 98 //  6. up only: no other Service holds one of our NodePorts
 99 //  7. all but down: the InternalIP of the node
100 //
101 // Every failure is a *BenchError.
102 func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
103     var res PreflightResult
104     if err := p.Validate(); err != nil {
105         return res, err
106     }
107     pf := preflight{r: r, p: p}
108     if err := pf.checkContext(ctx); err != nil {
109         return res, err
110     }
111     if err := pf.checkReachable(ctx); err != nil {
112         return res, err
113     }
114     for _, perm := range permissionsByOp[op] {
115         if err := pf.checkPermission(ctx, perm); err != nil {
116             return res, err
117         }
118     }
119     res, err := pf.checkNamespace(ctx, op)
120     if err != nil {
121         return res, err
122     }
123     if op == OpUp {
124         if err := pf.checkNodePorts(ctx); err != nil {
125             return res, err
126         }
127     }
128     if op != OpDown {
129         if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
130             return res, err
131         }
132     }
133     return res, nil
134 }
135 
136 type preflight struct {
137     r Runner
138     p Params
139 }
140 
141 // local runs a call that does not reach the API server.
142 func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
143     out, errOut, err := pf.r.Run(ctx, nil, args...)
144     return string(out), string(errOut), err
145 }
146 
147 // remote runs a call that reaches the API server, under a request timeout.
148 func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
149     return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
150 }
151 
152 // command is the kubectl command line a user can run to repeat a call.
153 func (pf preflight) command(args ...string) string {
154     return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
155 }
156 
157 // failure turns a failed kubectl call into a BenchError whose kind comes from
158 // the stderr. Neither the stderr nor the sub-process error reaches the message.
159 func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
160     kind := classifyKubectl(stderr)
161     reason := "kubectl failed"
162     switch kind {
163     case Forbidden:
164         reason = "the API server refused the request (forbidden)"
165     case ClusterUnreachable:
166         reason = "the cluster did not answer"
167     }
168     return &BenchError{
169         Kind:  kind,
170         Cause: "could not " + what + ": " + reason,
171         Check: pf.command(args...),
172         Err:   err,
173     }
174 }
175 
176 func (pf preflight) checkContext(ctx context.Context) error {
177     args := []string{"config", "get-contexts", "-o", "name"}
178     out, errOut, err := pf.local(ctx, args...)
179     if err != nil {
180         return pf.failure("list the kubeconfig contexts", args, errOut, err)
181     }
182     for _, line := range strings.Split(out, "\n") {
183         if strings.TrimSpace(line) == pf.p.Context {
184             return nil
185         }
186     }
187     return &BenchError{
188         Kind:  ContextNotFound,
189         Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
190         Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
191     }
192 }
193 
194 func (pf preflight) checkReachable(ctx context.Context) error {
195     args := []string{"get", "--raw", "/readyz"}
196     _, errOut, err := pf.remote(ctx, args...)
197     if err == nil {
198         return nil
199     }
200     // A refusal (an expired token, a 403) is not an absent cluster: say so.
201     // Anything else, classified or not, means the server did not answer.
202     if classifyKubectl(errOut) == Forbidden {
203         return pf.failure("reach the API server", args, errOut, err)
204     }
205     return &BenchError{
206         Kind:  ClusterUnreachable,
207         Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
208         Check: pf.command(args...),
209         Err:   err,
210     }
211 }
212 
213 // checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
214 // non-zero exit, so the answer is read before the error.
215 func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
216     args := []string{"auth", "can-i", perm.verb, perm.resource}
217     where := "cluster-wide"
218     switch perm.scope {
219     case scopeNamespace:
220         args = append(args, "-n", pf.p.Namespace)
221         where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
222     case scopeAll:
223         args = append(args, "-A")
224         where = "in all namespaces"
225     }
226     out, errOut, err := pf.remote(ctx, args...)
227     answer := strings.TrimSpace(out)
228     switch {
229     case strings.HasPrefix(answer, "no"):
230         return &BenchError{
231             Kind:  Forbidden,
232             Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
233             Check: pf.command(args...),
234             Err:   err,
235         }
236     case err == nil && strings.HasPrefix(answer, "yes"):
237         return nil
238     }
239     return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
240 }
241 
242 // namespaceObject is the part of a Namespace the preflight reads.
243 type namespaceObject struct {
244     Metadata struct {
245         Labels map[string]string `json:"labels"`
246     } `json:"metadata"`
247 }
248 
249 func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
250     var res PreflightResult
251     ns := pf.p.Namespace
252     args := []string{"get", "namespace", ns, "-o", "json"}
253     out, errOut, err := pf.remote(ctx, args...)
254     switch {
255     case err != nil && isNotFound(errOut):
256         // Absent: only provision and status need it.
257         if op == OpProvision || op == OpStatus {
258             return res, &BenchError{
259                 Kind:  NamespaceMissing,
260                 Cause: fmt.Sprintf("namespace %q does not exist", ns),
261                 Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
262                 Err:   err,
263             }
264         }
265         return res, nil
266     case err != nil:
267         return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
268     }
269 
270     var obj namespaceObject
271     if err := json.Unmarshal([]byte(out), &obj); err != nil {
272         return res, &BenchError{
273             Kind:  Unclassified,
274             Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
275             Check: pf.command(args...),
276             Err:   err,
277         }
278     }
279     res.NamespaceExists = true
280     res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
281     if !res.NamespaceOurs {
282         return res, &BenchError{
283             Kind:  NamespaceForeign,
284             Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
285             Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
286         }
287     }
288     return res, nil
289 }
