306 // checkNodePorts reads every Service of the cluster: the list of taken
307 // NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
308 // them: that is a second up.
309 func (pf preflight) checkNodePorts(ctx context.Context) error {
310     args := []string{"get", "services", "-A", "-o", "json"}
311     out, errOut, err := pf.remote(ctx, args...)
312     if err != nil {
313         return pf.failure("list the Services of the cluster", args, errOut, err)
314     }
315     var list serviceList
