317         return &BenchError{
318             Kind:  Unclassified,
319             Cause: "kubectl answered with something that is not a Service list",
320             Check: pf.command(args...),
321             Err:   err,
322         }
323     }
324     var taken []string
325     for _, svc := range list.Items {
326         if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
327             continue
328         }
329         for _, port := range svc.Spec.Ports {
330             if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
331                 taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
332             }
333         }
