337             Kind:  NodePortTaken,
338             Cause: "NodePort " + strings.Join(taken, ", "),
339             Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
340         }
341     }
342     return nil
343 }
