 13 const (
 14     // destroyPollStart and destroyPollMax bound the interval between two reads
 15     // of a namespace that is still Terminating: it doubles from the first to
 16     // the second.
 17     destroyPollStart = time.Second
 18     destroyPollMax   = 10 * time.Second
 19 )
 20 
 21 // Destroy deletes the bench namespace, waits until it is gone, then reports the
 22 // PersistentVolumes left behind and removes the stored secrets. Deleting a
 23 // namespace cannot be undone, so the order is rigid:
 24 //
 25 //  1. RunPreflight(OpDown): the parameters (which refuse the namespaces the
 26 //     bench must never touch), the cluster, the permission, and the label of
 27 //     the namespace. A namespace without our label is refused here.
 28 //  2. A namespace that is absent is "nothing to delete": success, and the
 29 //     stored secrets of a bench that no longer exists are removed.
 30 //  3. One write, `delete namespace <ns> --wait=false`, issued once and never
 31 //     retried. Nothing else is ever written: a namespace stuck in Terminating
 32 //     is reported, not forced.
 33 //  4. The namespace is read until NotFound, or until p.DeleteTimeout.
 34 //  5. One read of the PersistentVolumes: one that still points at a claim of
 35 //     the namespace is a warning, not a failure (the data stays on the node).
 36 //  6. The stored secrets are removed, last, and only when the namespace is gone.
 37 //
 38 // Every failure is a *BenchError, except a cancelled context, which is
 39 // wrapped so that errors.Is(err, context.Canceled) holds. Nothing written to
 40 // out or to an error carries a secret.
 41 func Destroy(ctx context.Context, r Runner, clk Clock, store SecretStore, p Params, out io.Writer) error {
 42     res, err := RunPreflight(ctx, r, p, OpDown)
 43     if err != nil {
 44         return err
 45     }
 46     d := destroyer{r: r, clk: clk, p: p, out: out}
 47     if !res.NamespaceExists {
 48         d.say("nothing to delete: namespace %s does not exist", p.Namespace)
 49         return removeSecrets(store)
 50     }
 51     if err := d.deleteNamespace(ctx); err != nil {
 52         return err
 53     }
 54     if err := d.waitGone(ctx); err != nil {
 55         return err
 56     }
 57     d.warnAboutVolumes(ctx)
 58     d.say("namespace %s deleted", p.Namespace)
 59     return removeSecrets(store)
 60 }
 61 
 62 type destroyer struct {
 63     r   Runner
 64     clk Clock
 65     p   Params
 66     out io.Writer
 67 }
 68 
 69 func (d destroyer) say(format string, args ...any) {
 70     _, _ = fmt.Fprintf(d.out, "down: "+format+"\n", args...)
 71 }
 72 
 73 // command is the kubectl command line a user can run to repeat a call.
 74 func (d destroyer) command(args ...string) string {
 75     return "kubectl --context " + d.p.Context + " " + strings.Join(args, " ")
 76 }
 77 
 78 // removeSecrets drops the stored secrets of the bench. The error of the store
 79 // can name a path but never a secret.
 80 func removeSecrets(store SecretStore) error {
 81     if err := store.Remove(); err != nil {
 82         return &BenchError{
 83             Kind:  Unclassified,
 84             Cause: "the namespace is gone but the stored secrets could not be removed",
 85             Check: "fix the permissions of the secrets file, then run `mise run nexus-bench:down` again (it finds nothing to delete and retries the removal)",
 86             Err:   err,
 87         }
 88     }
 89     return nil
 90 }
 91 
 92 // deleteNamespace issues the one write of Destroy. It is not retried.
 93 func (d destroyer) deleteNamespace(ctx context.Context) error {
 94     ns := d.p.Namespace
 95     args := []string{"delete", "namespace", ns, "--wait=false", requestTimeout}
 96     _, errOut, err := d.r.Run(ctx, nil, args...)
 97     if err == nil || isNotFound(string(errOut)) {
 98         d.say("deleting namespace %s", ns)
 99         return nil
100     }
101     if ctx.Err() != nil {
102         return fmt.Errorf("delete namespace %s: %w", ns, ctx.Err())
103     }
104     kind := classifyKubectl(string(errOut))
105     cause := fmt.Sprintf("could not delete namespace %q: kubectl failed", ns)
106     if kind == Forbidden {
107         cause = fmt.Sprintf("could not delete namespace %q: the API server refused the request (forbidden)", ns)
108     }
109     return &BenchError{Kind: kind, Cause: cause, Check: d.command("auth", "can-i", "delete", "namespaces"), Err: err}
110 }
111 
112 // terminatingNamespace is the part of a Namespace the wait reads and reports.
113 type terminatingNamespace struct {
114     Spec struct {
115         Finalizers []string `json:"finalizers"`
116     } `json:"spec"`
117     Status struct {
118         Conditions []struct {
119             Type    string `json:"type"`
120             Status  string `json:"status"`
121             Message string `json:"message"`
122         } `json:"conditions"`
123     } `json:"status"`
124 }
125 
126 // describe lists what holds the namespace: its finalizers and its conditions.
127 func (n terminatingNamespace) describe() string {
128     finalizers := "none"
129     if len(n.Spec.Finalizers) > 0 {
130         finalizers = strings.Join(n.Spec.Finalizers, ", ")
131     }
132     var conds []string
133     for _, c := range n.Status.Conditions {
134         conds = append(conds, fmt.Sprintf("%s=%s (%s)", c.Type, c.Status, c.Message))
135     }
136     if len(conds) == 0 {
137         conds = []string{"none reported"}
138     }
139     return fmt.Sprintf("spec.finalizers: %s; status.conditions: %s", finalizers, strings.Join(conds, "; "))
140 }
141 
142 // waitGone reads the namespace until it is NotFound or p.DeleteTimeout passes.
143 func (d destroyer) waitGone(ctx context.Context) error {
144     ns := d.p.Namespace
145     args := []string{"get", "namespace", ns, "-o", "json"}
146     deadline := d.clk.Now().Add(d.p.DeleteTimeout)
147     interval := destroyPollStart
148     var last terminatingNamespace
149     for {
150         out, errOut, err := d.r.Run(ctx, nil, append(args, requestTimeout)...)
151         switch {
152         case err != nil && isNotFound(string(errOut)):
153             return nil
154         case err != nil && ctx.Err() != nil:
155             return fmt.Errorf("wait for namespace %s to go: %w", ns, ctx.Err())
156         case err != nil:
157             return &BenchError{
158                 Kind:  classifyKubectl(string(errOut)),
159                 Cause: fmt.Sprintf("could not read namespace %q while it terminates: kubectl failed", ns),
160                 Check: d.command(args...),
161                 Err:   err,
162             }
163         }
164         // An unreadable answer keeps the last description: the wait goes on.
165         var seen terminatingNamespace
166         if json.Unmarshal(out, &seen) == nil {
167             last = seen
168         }
169         remaining := deadline.Sub(d.clk.Now())
170         if remaining <= 0 {
171             return &BenchError{
172                 Kind:  Deadline,
173                 Cause: fmt.Sprintf("namespace %q is still Terminating after %s (%s)", ns, d.p.DeleteTimeout, last.describe()),
174                 Check: d.command(args...) + ", then clear what holds it; the bench never removes finalizers",
175             }
176         }
177         if err := d.clk.Sleep(ctx, min(interval, remaining)); err != nil {
178             return fmt.Errorf("wait for namespace %s to go: %w", ns, err)
179         }
180         interval = min(interval*2, destroyPollMax)
181     }
182 }
