186     Items []struct {
187         Metadata struct {
188             Name string `json:"name"`
189         } `json:"metadata"`
190         Spec struct {
191             ClaimRef *struct {
192                 Namespace string `json:"namespace"`
193             } `json:"claimRef"`
194         } `json:"spec"`
195         Status struct {
196             Phase string `json:"phase"`
197         } `json:"status"`
198     } `json:"items"`
199 }
