 29 // Read implements InitialPassword. A missing file is (_, false, nil); any other
 30 // failure is an error that carries neither the output of the command nor the
 31 // REDACTED.
 32 func (k *kubectlInitialPassword) Read(ctx context.Context) (string, bool, error) {
 33     stdout, stderr, err := k.runner.Run(ctx, nil, "-n", k.namespace, "exec", nexusDeployment, "--", "cat", initialPasswordFile)
 34     if err != nil {
