 11 // probeTimeout bounds one probe, connection included: the wait asks again at
 12 // its next round, so a short one is enough and a silent host costs little.
 13 const probeTimeout = 5 * time.Second
 14 
 15 // probeOp names the probe in its errors.
 16 const probeOp = "probe the Nexus status"
 17 
 18 // Prober tells whether a Nexus answers on baseURL ("http://host:port").
 19 type Prober interface {
 20     // Ready returns nil when GET <baseURL>/service/rest/v1/status answers 200,
 21     // and an error otherwise, whatever the reason.
 22     Ready(ctx context.Context, baseURL string) error
 23 }
 24 
 25 // httpProber is the Prober of the command.
 26 type httpProber struct {
 27     http *http.Client
 28 }
 29 
 30 // NewProber returns the Prober that asks the instance over HTTP. It sends one
 31 // unauthenticated GET, follows no redirection, goes through no proxy, and never
 32 // reads or reports the body of the answer.
 33 func NewProber() Prober {
 34     transport := http.DefaultTransport.(*http.Transport).Clone()
 35     transport.Proxy = nil
 36     // One probe per round: keeping the connection alive would only hold a socket
 37     // open on a pod that may be restarting.
 38     transport.DisableKeepAlives = true
 39     return &httpProber{http: &http.Client{
 40         Timeout:       probeTimeout,
 41         Transport:     transport,
 42         CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
 43     }}
 44 }
 45 
 46 // Ready implements Prober. The error is a *transportError (no answer) or an
 47 // *APIError (an answer other than 200); neither prints the URL or the body.
 48 func (pr *httpProber) Ready(ctx context.Context, baseURL string) error {
 49     target := strings.TrimRight(baseURL, "/") + restStatusPath
 50     req, err := http.NewRequestWithContext(ctx, http.MethodGet, target, nil)
 51     if err != nil {
 52         return &transportError{Op: probeOp, Err: err}
 53     }
 54     resp, err := pr.http.Do(req)
 55     if err != nil {
 56         return &transportError{Op: probeOp, Err: err}
 57     }
 58     defer func() { _ = resp.Body.Close() }()
 59     _, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, drainBytes))
 60     if resp.StatusCode != http.StatusOK {
 61         return &APIError{Op: probeOp, Status: resp.StatusCode}
 62     }
 63     return nil
 64 }
