  8 // Clock is the time the waits of the bench read and spend. Tests swap it for a
  9 // fake that never waits, so no test sleeps for real.
 10 type Clock interface {
 11     // Now returns the current time.
 12     Now() time.Time
 13     // Sleep waits for d, or until ctx is done. It returns ctx.Err() when ctx is
 14     // done, before sleeping if it already was, and nil after the whole wait. A
 15     // duration of zero or less returns at once (after the ctx check).
 16     Sleep(ctx context.Context, d time.Duration) error
 17 }
