 19 // realClock is the Clock of the command: the wall clock.
 20 type realClock struct{}
 21 
 22 // NewClock returns the real clock.
 23 func NewClock() Clock { return realClock{} }
 24 
 25 // Now implements Clock.
 26 func (realClock) Now() time.Time { return time.Now() }
 27 
 28 // Sleep implements Clock.
 29 func (realClock) Sleep(ctx context.Context, d time.Duration) error {
 30     if err := ctx.Err(); err != nil {
 31         return err
 32     }
 33     if d <= 0 {
 34         return nil
 35     }
 36     timer := time.NewTimer(d)
 37     defer timer.Stop()
 38     select {
 39     case <-ctx.Done():
 40         return ctx.Err()
 41     case <-timer.C:
 42         return nil
 43     }
 44 }

