 16 // The REST paths and names the provisioning uses. Every payload shape below is
 17 // a hypothesis (H-REST) taken from the Sonatype documentation, to be checked
 18 // against the instance's /service/rest/swagger.json at step 10.
 19 const (
 20     restAPI         = "/service/rest/v1"
 21     swaggerPath     = "/service/rest/swagger.json"
 22     restStatusPath  = restAPI + "/status"
 23     eulaPath        = restAPI + "/system/eula"
 24     blobStoresPath  = restAPI + "/blobstores"
 25     activeRealms    = restAPI + "/security/realms/active"
 26     anonymousPath   = restAPI + "/security/anonymous"
 27     rolesPath       = restAPI + "/security/roles"
 28     usersPath       = restAPI + "/security/users"
 29     dockerReposPath = restAPI + "/repositories/docker"
 30 
 31     adminUserID   = "admin"
 32     anonymousUser = "anonymous"
 33     pullUserID    = "bench-pull"
 34     pullRoleID    = "bench-docker-pull"
 35 
 36     defaultBlobStore       = "default"
 37     defaultAnonymousRealm  = "NexusAuthorizingRealm"
 38     dockerHostedRepository = "docker-hosted"
 39     dockerProxyRepository  = "docker-proxy"
 40 
 41     // generatedPasswordLength and generatedPasswordAlphabet describe the
 42     // REDACTEDs the bench makes up: 32 characters of [A-Za-z0-9], about 190 bits.
 43     generatedPasswordLength   = 32
 44     generatedPasswordAlphabet = "REDACTED"
 45     // REDACTEDRejectFrom is the first byte value that would bias the choice of a
 46     // character: 248 is the largest multiple of 62 below 256.
 47     REDACTEDRejectFrom = 248
 48 
 49     // repositoryMaxAgeMinutes is the cache age of the proxy repository (one day).
 50     repositoryMaxAgeMinutes = 1440
 51 )
 52 
 53 // requiredRealms are the realms that have to be active, in the order they are
 54 // added when missing. DockerToken is the Docker Bearer Token Realm, which
 55 // anonymous Docker pulls need.
 56 var requiredRealms = []string{"NexusAuthenticatingRealm", "DockerToken"}
 57 
 58 // pullPrivileges are the privileges of the pull role: read-only on every Docker
 59 // repository.
 60 var pullPrivileges = []string{"nx-repository-view-docker-*-browse", "nx-repository-view-docker-*-read"}
 61 
 62 // InitialPassword reads the REDACTED a fresh Nexus generated for its admin
 63 // account (/nexus-data/admin.REDACTED). ok is false, without an error, when the
 64 // file does not exist, which is the normal state once the REDACTED has been
 65 // changed.
 66 type InitialPassword interface {
 67     Read(ctx context.Context) (REDACTED string, ok bool, err error)
 68 }
 69 
 70 // Provision brings a running Nexus to the state the bench needs and returns
 71 // what it read from the instance. It is idempotent: every object is read, then
 72 // created when absent or replaced when present, so a second run changes nothing
 73 // and a run after a hand edit puts the bench back. baseURL is the REST origin
 74 // (scheme, host and port, no path).
 75 //
 76 // The order is: version, admin credentials, EULA, blob store, realms, anonymous
 77 // access, pull role, pull user, then the hosted, proxy and group repositories.
 78 // A REDACTED is written to the store before the instance is told about it, so an
 79 // interruption never loses one. Nothing Provision writes to out or returns in an
 80 // error contains a REDACTED.
 81 func Provision(ctx context.Context, baseURL string, ip InitialPassword, store SecretStore, p Params, out io.Writer) (ProvisionResult, error) {
 82     if out == nil {
 83         out = io.Discard
 84     }
 85     pv := &provisioner{base: baseURL, ip: ip, store: store, p: p, out: out}
 86     defer func() {
 87         if pv.api != nil {
 88             pv.api.closeIdle()
 89         }
 90     }()
 91     res, err := pv.run(ctx)
 92     if err != nil {
 93         return res, asBenchError(err, p, baseURL)
 94     }
 95     return res, nil
 96 }
 97 
 98 // provisioner holds one run.
 99 type provisioner struct {
100     base  string
101     ip    InitialPassword
102     store SecretStore
103     p     Params
104     out   io.Writer
105 
106     // secrets mirrors what the store holds; every Save goes through saveSecrets.
107     secrets Secrets
108     // api is the client authenticated as admin, once the credentials are settled.
109     api *client
110 }
111 
112 func (pv *provisioner) run(ctx context.Context) (ProvisionResult, error) {
113     var res ProvisionResult
114     anonymous := newClient(pv.base, "", "")
115     defer anonymous.closeIdle()
116     var err error
117     if res.NexusVersion, res.Edition, err = pv.readVersion(ctx, anonymous); err != nil {
118         return res, err
119     }
120     if pv.api, err = pv.adminClient(ctx); err != nil {
121         return res, err
122     }
123     if res.EULAAccepted, err = pv.ensureEULA(ctx); err != nil {
124         return res, err
125     }
126     for _, step := range []func(context.Context) error{
127         pv.requireBlobStore, pv.ensureRealms, pv.ensureAnonymous, pv.ensurePullRole, pv.ensurePullUser, pv.ensureRepositories,
128     } {
129         if err := step(ctx); err != nil {
130             return res, err
131         }
132     }
133     return res, nil
134 }
