526 // repositories returns the three Docker repositories, in the order they can be
527 // created: the group needs its members.
528 func (pv *provisioner) repositories() []repositorySpec {
529     storage := func(extra map[string]any) map[string]any {
530         s := map[string]any{"blobStoreName": defaultBlobStore, "strictContentTypeValidation": true}
531         for k, v := range extra {
532             s[k] = v
533         }
534         return s
535     }
536     // Anonymous pulls need the Docker API without a forced Basic auth.
537     docker := func(extra map[string]any) map[string]any {
538         d := map[string]any{"v1Enabled": false, "forceBasicAuth": false}
539         for k, v := range extra {
540             d[k] = v
541         }
542         return d
543     }
544     return []repositorySpec{
545         {"hosted", dockerHostedRepository, map[string]any{
546             "name": dockerHostedRepository, "online": true,
547             "storage": storage(map[string]any{"writePolicy": "ALLOW"}),
548             "docker":  docker(nil),
549         }},
550         {"proxy", dockerProxyRepository, map[string]any{
551             "name": dockerProxyRepository, "online": true,
552             "storage": storage(nil),
553             "docker":  docker(nil),
554             "proxy": map[string]any{
555                 "remoteUrl": pv.p.UpstreamURL, "contentMaxAge": repositoryMaxAgeMinutes, "metadataMaxAge": repositoryMaxAgeMinutes,
556             },
557             "dockerProxy":   map[string]any{"indexType": "REGISTRY"},
558             "negativeCache": map[string]any{"enabled": true, "timeToLive": repositoryMaxAgeMinutes},
559             "httpClient":    map[string]any{"blocked": false, "autoBlock": true},
560         }},
561         {"group", dockerGroupRepository, map[string]any{
562             "name": dockerGroupRepository, "online": true,
563             "storage": storage(nil),
564             "docker":  docker(map[string]any{"httpPort": dockerContainerPort}),
565             "group":   map[string]any{"memberNames": []string{dockerHostedRepository, dockerProxyRepository}},
566         }},
567     }
568 }
569 
570 func (pv *provisioner) ensureRepositories(ctx context.Context) error {
571     for _, repo := range pv.repositories() {
572         collection := dockerReposPath + "/" + repo.kind
573         found, err := pv.api.get(ctx, fmt.Sprintf("read the %s repository %s", repo.kind, repo.name), collection+"/"+repo.name, nil, nil)
574         if err != nil {
575             return err
576         }
577         if !found {
578             op := fmt.Sprintf("create the %s repository %s", repo.kind, repo.name)
579             if err := pv.api.write(ctx, op, http.MethodPost, collection, repo.config); err != nil {
580                 return err
581             }
582             pv.say("%s repository %s created", repo.kind, repo.name)
583             continue
584         }
585         op := fmt.Sprintf("update the %s repository %s", repo.kind, repo.name)
586         if err := pv.api.write(ctx, op, http.MethodPut, collection+"/"+repo.name, repo.config); err != nil {
587             return err
588         }
589         pv.say("%s repository %s updated", repo.kind, repo.name)
590     }
591     return nil
592 }
